import json
from datetime import datetime
def task_func(json_data):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        return False
    utc_dt = data.get('utc_datetime')
    if not utc_dt:
        return False
    try:
        try:
            dt = datetime.fromisoformat(utc_dt.replace('Z', '+00:00'))
        except ValueError:
            dt = datetime.strptime(utc_dt, "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return False
    return dt.weekday() >= 5

