import json
def task_func():
    class JSONPostHandler(http.server.BaseHTTPRequestHandler):
        def _send_response(self, status_code, payload):
            response_body = json.dumps(payload).encode("utf-8")
            self.send_response(status_code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(response_body)))
            self.end_headers()
            self.wfile.write(response_body)

        def do_POST(self):
            content_type = self.headers.get("Content-Type", "")
            if content_type.split(";")[0].strip().lower() != "application/json":
                payload = {"status": "error", "message": "Content-Type header is not application/json"}
                self._send_response(400, payload)
                return
            try:
                content_length = int(self.headers.get("Content-Length", "0"))
            except ValueError:
                content_length = 0
            body = self.rfile.read(content_length) if content_length > 0 else b""
            try:
                data = json.loads(body.decode("utf-8") or "{}")
            except (json.JSONDecodeError, UnicodeDecodeError):
                payload = {"status": "error", "message": "No data received"}
                self._send_response(400, payload)
                return
            if "data" not in data:
                payload = {"status": "error", "message": "No data received"}
                self._send_response(400, payload)
                return
            payload = {"status": "success", "message": "Data received successfully."}
            self._send_response(200, payload)
    return JSONPostHandler

