import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.isfile(file_path):
        raise ValueError("File does not exist")
    with open(file_path, "r") as f:
        data = json.load(f)
    if not isinstance(data, dict):
        raise ValueError("JSON root must be an object")
    schema_props = INPUT_JSON.get("properties", {})
    required_fields = INPUT_JSON.get("required", [])
    for field in required_fields:
        if field not in data:
            raise ValueError(f"Missing required field: {field}")
        expected_type = schema_props.get(field, {}).get("type", None)
        if expected_type is not None and not isinstance(data[field], expected_type):
            raise ValueError(f"Field '{field}' must be of type {expected_type.__name__}")
    email_value = data.get("email", None)
    if email_value is None or not isinstance(email_value, str):
        raise ValueError("Email field must be a string")
    if not re.match(EMAIL_REGEX, email_value):
        raise ValueError("Invalid email format")
    if attribute not in data:
        raise ValueError(f"Attribute '{attribute}' not found in JSON")
    expected_attr_type = schema_props.get(attribute, {}).get("type", None)
    if expected_attr_type is not None and not isinstance(data[attribute], expected_attr_type):
        raise ValueError(f"Attribute '{attribute}' must be of type {expected_attr_type.__name__}")
    return data[attribute]

