from glob import glob
def task_func(directory, string):
    def contains_string(obj, target):
        if isinstance(obj, dict):
            for v in obj.values():
                if contains_string(v, target):
                    return True
        elif isinstance(obj, list):
            for item in obj:
                if contains_string(item, target):
                    return True
        else:
            if str(obj) == target:
                return True
        return False

    pattern = directory.rstrip('/') + '/**/*.json'
    file_paths = glob(pattern, recursive=True)
    matched_files = []

    for path in file_paths:
        try:
            with open(path, 'r') as f:
                data = json.load(f)
        except Exception:
            continue
        if contains_string(data, string):
            matched_files.append(path)

    return matched_files

