import pandas as pd
def task_func(json_str):
    if not json_str or not json_str.strip():
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return pd.DataFrame()
    if not isinstance(data, dict):
        return pd.DataFrame()
    def parse_number(s):
        match = re.fullmatch(r'[+-]?(?:\d+(?:\.\d*)?|\.\d+)', s.strip())
        if match:
            return float(match.group())
        return None
    normalized = {}
    for k, v in data.items():
        if isinstance(v, (int, float)):
            normalized[k] = float(v) * 2
        elif isinstance(v, list):
            new_list = []
            for item in v:
                if isinstance(item, (int, float)):
                    new_list.append(float(item) * 2)
                elif isinstance(item, str):
                    num = parse_number(item)
                    if num is not None:
                        new_list.append(num * 2)
                    else:
                        new_list.append(item)
                else:
                    new_list.append(item)
            normalized[k] = new_list
        elif isinstance(v, str):
            num = parse_number(v)
            if num is not None:
                normalized[k] = num * 2
            else:
                def repl(m):
                    return str(float(m.group()) * 2)
                new_v = re.sub(r'[+-]?(?:\d+(?:\.\d*)?|\.\d+)', repl, v)
                normalized[k] = new_v
        else:
            normalized[k] = v
    if not normalized:
        return pd.DataFrame()
    try:
        df = pd.DataFrame.from_dict(normalized)
    except ValueError:
        return pd.DataFrame()
    for col in df.columns:
        df[col] = pd.to_numeric(df[col], errors='ignore')
    return df

