import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    if not json_data or not isinstance(json_data, str):
        raise ValueError("Invalid or empty JSON data")

    try:
        data = json.loads(json_data)
    except Exception as e:
        raise ValueError("Malformed JSON data") from e

    if not data:
        raise ValueError("JSON data is empty")

    if not isinstance(data, (list, tuple)):
        raise ValueError("JSON data must be a list of records")

    countries = []
    populations = []

    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each record must be a dictionary")
        if "Country" not in item or "Population" not in item:
            raise ValueError("Each record must contain 'Country' and 'Population' keys")

        country = item["Country"]
        population = item["Population"]

        if not isinstance(country, str):
            raise ValueError("Country names must be strings")

        if not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")

        if population < 0:
            raise ValueError("Population cannot be negative")

        population_int = int(math.floor(population))
        countries.append(country)
        populations.append(population_int)

    df = pd.DataFrame({"Country": countries, "Population": populations})

    if not os.path.isdir(output_dir):
        raise IOError("Output directory does not exist")

    file_path = os.path.join(output_dir, file_name)

    try:
        df.to_csv(file_path, index=False)
    except Exception as e:
        raise IOError("Failed to write CSV file") from e

    return file_path, df

