REPLACE_NONE = "None"
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {"data": None, "value_counts": Counter()}
    email_pattern = re.compile(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b')
    values = []
    def process(obj):
        if isinstance(obj, dict):
            new_dict = {}
            for k, v in obj.items():
                processed_v = process(v)
                if processed_v is not None:
                    new_dict[k] = processed_v
            return new_dict
        elif isinstance(obj, list):
            new_list = []
            for item in obj:
                processed_item = process(item)
                if processed_item is not None:
                    new_list.append(processed_item)
            return new_list
        elif isinstance(obj, str):
            if email_pattern.search(obj):
                val = REPLACE_NONE
            else:
                val = obj
            values.append(val)
            return val
        else:
            if obj is None:
                return None
            values.append(obj)
            return obj
    processed_data = process(data)
    value_counts = Counter(values)
    return {"data": processed_data, "value_counts": value_counts}
